import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './ApplyForm.css';

function ApplyForm() {
  const [formData, setFormData] = useState({
    name: '',
    cuisine: '',
    region: '',
    highlights: '',
    phone: ''
  });

  const [errors, setErrors] = useState({});
  const [success, setSuccess] = useState('');
  const navigate = useNavigate();

  const validate = () => {
    let errs = {};
    if (!formData.name) errs.name = "Name is required";
    if (!formData.cuisine) errs.cuisine = "Cuisine Specialties are required";
    if (!formData.region) errs.region = "Operating Region is required";
    if (!formData.highlights) errs.highlights = "Menu Highlights are required";
    if (!formData.phone) {
      errs.phone = "Phone Number is required";
    } else if (formData.phone.length !== 10) {
      errs.phone = "Invalid phone number format";
    }
    return errs;
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    try {
      const res = await fetch('http://localhost:8080/addVendor', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (res.ok) {
        setSuccess("Application submitted successfully!");
        setFormData({ name: '', cuisine: '', region: '', highlights: '', phone: '' });
        setTimeout(() => navigate('/getAllVendors'), 1500);
      } else {
        console.error("Error submitting form");
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="form-container">
      <h2>Apply to Become a Food Truck Vendor</h2>
      {success && <p className="success">{success}</p>}
      <form onSubmit={handleSubmit}>
        <label htmlFor="name">Name:</label>
        <input name="name" id="name" value={formData.name} onChange={handleChange} />
        {errors.name && <span className="error">{errors.name}</span>}

        <label htmlFor="cuisine">Cuisine Specialties:</label>
        <input name="cuisine" id="cuisine" value={formData.cuisine} onChange={handleChange} />
        {errors.cuisine && <span className="error">{errors.cuisine}</span>}

        <label htmlFor="region">Operating Region:</label>
        <select name="region" id="region" value={formData.region} onChange={handleChange}>
          <option value="">Select an operating region</option>
          <option value="Chennai">Chennai</option>
          <option value="Bangalore">Bangalore</option>
        </select>
        {errors.region && <span className="error">{errors.region}</span>}

        <label htmlFor="highlights">Menu Highlights:</label>
        <input name="highlights" id="highlights" value={formData.highlights} onChange={handleChange} />
        {errors.highlights && <span className="error">{errors.highlights}</span>}

        <label htmlFor="phone">Phone Number:</label>
        <input name="phone" id="phone" value={formData.phone} onChange={handleChange} />
        {errors.phone && <span className="error">{errors.phone}</span>}

        <button type="submit">Submit Application</button>
        <button type="button" onClick={() => navigate('/')}>Back</button>
      </form>
    </div>
  );
}

export default ApplyForm;
